import itertools
import time

n = 19
fixed_seq = {4: -1, 12: 1, 13: -1}
fixed_c = {1: -1, 2: 0, 7: -3}

def compute_c(seq, k):
    total = 0
    for i in range(n - k):
        if seq[i] is None or seq[i+k] is None:
            return None
        total += seq[i] * seq[i+k]
    return total

def check_partial_c(seq, k, target):
    current = 0
    unknown_terms = 0
    for i in range(n - k):
        a = seq[i]
        b = seq[i+k]
        if a is not None and b is not None:
            current += a * b
        else:
            unknown_terms += 1
    min_possible = current - unknown_terms
    max_possible = current + unknown_terms
    return min_possible <= target <= max_possible

def check_sum_squares_bound(seq, max_sum=46):
    s = 0
    for k in range(1, n):
        c = compute_c(seq, k)
        if c is not None:
            s += c * c
            if s > max_sum:
                return False
    return True

def search(seq, idx):
    if idx == n:
        for k, target in fixed_c.items():
            if compute_c(seq, k) != target:
                return None
        s = sum(compute_c(seq, k)**2 for k in range(1, n))
        if s <= 46:
            return seq[:]
        return None

    if seq[idx] is not None:
        return search(seq, idx+1)

    for val in [-1, 1]:
        seq[idx] = val
        ok = True
        for k, target in fixed_c.items():
            c = compute_c(seq, k)
            if c is not None and c != target:
                ok = False
                break
            if not check_partial_c(seq, k, target):
                ok = False
                break
        if ok:
            if check_sum_squares_bound(seq):
                res = search(seq, idx+1)
                if res is not None:
                    return res
        seq[idx] = None
    return None

seq = [None]*n
for i, v in fixed_seq.items():
