start = time.time()
result = search(seq, 0)
print("Time:", time.time() - start)
print("Result:", result)
if result:
    for k in range(1, n):
        c = sum(result[i]*result[i+k] for i in range(n-k))
        print(f"c[{k}]={c}")
    s = sum(sum(result[i]*result[i+k] for i in range(n-k))**2 for k in range(1, n))
    print("Sum squares:", s)

