import itertools
import time

n = 19
fixed_seq = {4: -1, 12: 1, 13: -1}
fixed_c = {1: -1, 2: 0, 7: -3}

free_indices = [i for i in range(n) if i not in fixed_seq]

count = 0
solutions = []
start = time.time()

for bits in itertools.product([-1, 1], repeat=len(free_indices)):
    seq = [0]*n
    for i, v in fixed_seq.items():
        seq[i] = v
    for idx, val in zip(free_indices, bits):
        seq[idx] = val

    # Check fixed c constraints
    ok = True
    for k, target in fixed_c.items():
        c = sum(seq[i]*seq[i+k] for i in range(n-k))
        if c != target:
            ok = False
            break
    if not ok:
        continue

    # Compute sum of squares
    s = 0
    for k in range(1, n):
        c = sum(seq[i]*seq[i+k] for i in range(n-k))
        s += c*c
        if s > 46:
            break
    if s <= 46:
        solutions.append((seq[:], s))

print("Time:", time.time() - start)
print("Number of solutions found:", len(solutions))
for seq, s in solutions[:5]:
